BEGIN;
ALTER TABLE otro_servicio DROP CONSTRAINT otro_servicio_tipo_check;
ALTER TABLE otro_servicio ADD CONSTRAINT otro_servicio_tipo_check CHECK (tipo IN ('COBERTURA_EVENTOS','GESTION_ADMINISTRATIVA','TALLER','CAPACITACION','OTRO','GESTION_DPC','CAPACITACION_PERSONAL','REUNION_OPERATIVA','GESTIONES_VARIAS','LABOR_PREVENTIVA','INFORME','PROTECCION_SERVICIOS','SERVICIO_ESPECIAL','SERVICIO_FUNEBRE','SERVICIO_OPERATIVO','SIMULACRO','SUMINISTRO_COMBUSTIBLE','SUMINISTRO_AGUA','TRASLADO_BOMBEROS','TRASLADO_PACIENTES','VIAJE_AGUA','RECORRIDO'));
ALTER TABLE unidad DROP CONSTRAINT unidad_estado_check;
ALTER TABLE unidad ADD CONSTRAINT unidad_estado_check CHECK (estado IN ('DISPONIBLE','EN_EMERGENCIA','EN_SERVICIO','MANTENIMIENTO'));
UPDATE unidad u SET estado='EN_SERVICIO' FROM salida_unidad s
WHERE s.unidad_id=u.id AND s.otro_servicio_id IS NOT NULL AND s.retorno IS NULL AND u.estado='EN_EMERGENCIA';
COMMIT;
